/* Offline companion UI. No dependencies, no external assets, no hidden fixtures.
 * All gameplay goes through the same server-side ArenaService as the Next app. */
'use strict';
const locale=window.AgentForgeLocale;
const $=(selector,root=document)=>root.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const uri=value=>encodeURIComponent(String(value??''));
const localeTag=()=>locale?.get()==='zh-CN'?'zh-CN':'en-US';
const num=value=>new Intl.NumberFormat(localeTag()).format(Math.round(value||0));
const pct=value=>new Intl.NumberFormat(localeTag(),{style:'percent',maximumFractionDigits:1}).format(value||0);
const money=value=>{if(value===null||value===undefined)return locale?.get()==='zh-CN'?'未知':'unknown';const fractionDigits=value===0?2:value<0.01?5:3;return new Intl.NumberFormat(localeTag(),{style:'currency',currency:'USD',minimumFractionDigits:fractionDigits,maximumFractionDigits:fractionDigits}).format(value);};
const time=value=>{const numeric=Number(value)||0,amount=numeric>=1000?Number((numeric/1000).toFixed(2)):Math.round(numeric),formatted=`${new Intl.NumberFormat(localeTag(),{maximumFractionDigits:2}).format(amount)}${numeric>=1000?(locale?.get()==='zh-CN'?'秒':'s'):(locale?.get()==='zh-CN'?'毫秒':'ms')}`;return `<span data-locale-duration="${numeric}">${esc(formatted)}</span>`;};
const date=value=>{const formatted=new Date(value).toLocaleDateString(localeTag(),{year:'numeric',month:'short',day:'numeric'});return `<time data-locale-date="${esc(value)}">${esc(formatted)}</time>`;};
const paths={ArrowRight:'M5 12h14m-6-6 6 6-6 6',ArrowUpRight:'M7 17 17 7M7 7h10v10',Code2:'m8 8-4 4 4 4m8-8 4 4-4 4m-3-12-2 24',Braces:'M8 3H6v7l-3 2 3 2v7h2m8-18h2v7l3 2-3 2v7h-2',Cpu:'M8 8h8v8H8zM5 5h14v14H5zM9 1v4m6-4v4m-6 14v4m6-4v4M1 9h4m-4 6h4m14-6h4m-4 6h4',Sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',ShieldCheck:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-6',Shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z',Inbox:'M4 4h16l2 12v4H2v-4zM2 14h6l2 3h4l2-3h6',Trophy:'M7 3h10v7a5 5 0 0 1-10 0zM7 5H3v3a5 5 0 0 0 4 4m10-7h4v3a5 5 0 0 1-4 4m-5 3v6m-4 0h8',Users:'M8 4a4 4 0 1 0 0 8 4 4 0 0 0 0-8m-7 17v-2a7 7 0 0 1 14 0v2M17 4a4 4 0 0 1 0 8m0 3a6 6 0 0 1 6 6',Zap:'m13 2-9 12h7l-1 8 10-12h-7z',Activity:'M2 12h4l3-9 6 18 3-9h4',Boxes:'m12 3 9 5-9 5-9-5zm-9 5v10l9 5 9-5V8m-9 5v10',GitFork:'M7 3a2 2 0 1 0 0 4 2 2 0 0 0 0-4m10 0a2 2 0 1 0 0 4 2 2 0 0 0 0-4M7 7v4a5 5 0 0 0 5 5m5-9v4a5 5 0 0 1-5 5m0 0v3m0 0a2 2 0 1 0 0 4 2 2 0 0 0 0-4',Wrench:'m14 6 4 4 4-4a7 7 0 0 1-9 9L5 23l-4-4 8-8a7 7 0 0 1 9-9z',Lock:'M5 10h14v11H5zm3 0V6a4 4 0 0 1 8 0v4',Settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m-2-6h4l1 3 3 1 3-1 2 4-2 3 1 3 1 3-4 2-3-2-3 1-3 1-2-4 2-3-1-3-1-3 4-2z',LogOut:'M9 3H3v18h6m6-15 6 6-6 6m-7-6h13',Plus:'M12 5v14M5 12h14',Search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',Play:'m7 4 14 8-14 8z',Save:'M4 3h13l4 4v14H3V3zm3 0v6h10V3M7 21v-8h10v8',Send:'m2 2 20 10-20 10 4-10zm4 10h16',Copy:'M8 8h13v13H8zM4 16H2V2h14v2',Trash2:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',RotateCcw:'M3 9a9 9 0 1 1 0 6M3 3v6h6',ChevronRight:'m9 5 7 7-7 7',ChevronDown:'m5 9 7 7 7-7',Check:'m4 12 5 5 11-11',X:'m5 5 14 14M19 5 5 19',Timer:'M12 6a8 8 0 1 0 0 16 8 8 0 0 0 0-16M9 2h6m-3 4V2m0 8v5l3 2',Terminal:'m4 6 6 6-6 6m9 0h7',ArrowDownToLine:'M12 2v14m-6-6 6 6 6-6M4 22h16',ArrowUpFromLine:'M12 18V4m-6 6 6-6 6 6M4 22h16',Download:'M12 2v14m-5-5 5 5 5-5M3 16v6h18v-6',Eye:'M2 12s4-8 10-8 10 8 10 8-4 8-10 8S2 12 2 12zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',Target:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20m0 5a5 5 0 1 0 0 10 5 5 0 0 0 0-10m0 3v4',Calendar:'M3 5h18v16H3zM7 2v6m10-6v6M3 11h18',Calculator:'M5 2h14v20H5zM8 5h8v4H8zm0 8h1m3 0h1m3 0h1m-9 4h1m3 0h1m3 0h1',Github:'M9 20c-5 2-5-2-7-2m14 4v-4c0-1 0-2-1-3 4 0 7-2 7-6 0-2-1-3-2-4 0-1 0-3-1-4-2 0-3 1-4 2-3-1-5-1-8 0C6 2 5 1 3 1 2 2 2 4 3 5 1 6 1 7 1 9c0 4 3 6 7 6-1 1-1 2-1 3v4'};
const icon=(name,size=16)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.Boxes}"/></svg>`;
const S={user:null,boot:null,register:false,routeId:0,board:{sort:'overall',tier:'demo',problemId:''},builder:null,skills:[],tools:[],providers:null,challenge:null};
async function readResponsePayload(response){try{return await response.json();}catch{return undefined;}}
function normalizeClientError(payload,fallback,status){const envelope=payload&&typeof payload==='object'&&'error' in payload?payload.error:payload;let message=fallback,code; if(typeof envelope==='string'&&envelope.trim())message=envelope.slice(0,4000);else if(envelope&&typeof envelope==='object'&&!Array.isArray(envelope)){if(typeof envelope.message==='string'&&envelope.message.trim())message=envelope.message.slice(0,4000);if(typeof envelope.code==='string'&&/^[A-Z][A-Z0-9_]{1,99}$/.test(envelope.code))code=envelope.code;}const error=new Error(message);error.name='ApiError';error.status=status;error.code=code;return error;}
function displayError(error){if(error&&typeof error==='object'){const message=typeof error.message==='string'?error.message:'';const code=typeof error.code==='string'?error.code:undefined;return locale?.errorMessage(code,message)||locale?.translate(message)||message||'Request failed.';}return locale?.translate(String(error||'Request failed.'))||String(error||'Request failed.');}
async function request(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await readResponsePayload(response);if(!response.ok)throw normalizeClientError(data,'Request failed.',response.status);return data;}
const api=(path,options)=>request(`/api/arena/${path}`,options);
const post=(path,body)=>api(path,{method:'POST',body:JSON.stringify(body)});
function toast(message,error=false){const node=document.createElement('div');node.className=`toast${error?' error':''}`;node.textContent=locale?.translate(message)||message;$('#toasts').append(node);while($('#toasts').children.length>3)$('#toasts').firstElementChild.remove();setTimeout(()=>node.remove(),5000);}
const avatar=(name,index=3,large=false)=>`<span class="avatar rank-${index}${large?' large':''}">${esc(String(name).slice(0,2).toUpperCase())}</span>`;
const chip=(text,color='')=>`<span class="chip ${color}">${esc(text)}</span>`;
const button=(text,action,style='',extra='')=>`<button type="button" class="button ${style}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,href,style='')=>`<a href="${esc(href)}" class="button ${style}">${text}</a>`;
const field=(label,name,value='',extra='')=>`<div class="field"><label class="label" for="${name}">${esc(label)}</label><input id="${name}" name="${name}" value="${esc(value)}" ${extra}></div>`;
const textField=(label,name,value='',extra='')=>`<div class="field"><label class="label" for="${name}">${esc(label)}</label><textarea id="${name}" name="${name}" rows="4" ${extra}>${esc(value)}</textarea></div>`;
const heading=(eyebrow,title,description='',action='')=>`<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div>${action}</div>`;
const section=(title,count,href='',label='View all')=>`<div class="section-heading"><div class="heading-label"><h2>${esc(title)}</h2>${count!==undefined?`<span class="count">${count}</span>`:''}</div>${href?`<a class="section-link" href="${esc(href)}">${label} ${icon('ArrowUpRight',12)}</a>`:''}</div>`;
const empty=(title,description,action='')=>`<div class="empty-state">${icon('Boxes',26)}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;
const footer=()=>`<footer class="site-footer"><span><b class="muted" data-no-locale>AgentForge</b> &nbsp; <span>BUILD AI. BEAT PROBLEMS.</span></span><span><span>SIMULATION / LOCAL-FIRST MVP</span> &nbsp; ${icon('Zap',11)}</span></footer>`;
const laneNote=tier=>`<div class="callout small ${tier==='demo'?'purple':''}">${icon(tier==='verified'?'ShieldCheck':'Activity',14)} ${tier==='demo'?'Demo lane: simulated model behavior and seeded scores. No paid API calls.':tier==='byok'?'BYOK lane: a custom gateway can observe test inputs and report its own usage. These scores are not verified.':'Verified lane: server-owned platform provider, known pricing, sealed tests.'}</div>`;
const problemIcon=p=>p.judge==='json'?'Braces':p.judge==='enum'?'Inbox':'ShieldCheck';
function languageToggle(){const current=locale?.get()==='zh-CN'?'zh-CN':'en';return `<div id="locale-switch" class="flex items-center gap-1" role="group" aria-label="${locale?.t(current==='en'?'language.label':'language.label')||'Language'}"><button type="button" class="button small ghost ${current==='en'?'active':''}" data-action="set-locale" data-locale="en" aria-pressed="${current==='en'}" aria-label="English">EN</button><button type="button" class="button small ghost ${current==='zh-CN'?'active':''}" data-action="set-locale" data-locale="zh-CN" aria-pressed="${current==='zh-CN'}" aria-label="简体中文">简中</button></div>`;}
function refreshLocaleControls(){const current=$('#locale-switch');if(current)current.outerHTML=languageToggle();}
function localize(){locale?.apply();}
function header(){const path=location.pathname;return `<header class="site-header"><a class="brand" href="/" aria-label="AgentForge" data-no-locale><span class="brand-mark"><span>A</span></span><span>Agent<span class="accent">Forge</span></span></a><nav class="site-nav" aria-label="Main navigation">${[['/','Arena'],['/challenges','Challenges'],['/leaderboard','Leaderboard'],['/workshop','Workshop']].map(([href,label])=>`<a href="${href}" class="${path===href||href!=='/'&&path.startsWith(href)?'active':''}">${label}</a>`).join('')}</nav><div class="header-actions"><span class="season-pill"><span class="live-dot"></span>SEASON 00</span>${languageToggle()}${S.user?`<a href="/providers" class="button ghost icon" aria-label="Provider settings">${icon('Settings')}</a><a href="/profile/me" class="flex items-center gap-2">${avatar(S.user.name)}<span class="small header-user-name" data-no-locale>${esc(S.user.name)}</span></a>${button(icon('LogOut'),'logout','ghost icon','aria-label="Sign out"')}`:link('Enter the arena '+icon('ArrowRight',13),'/login','primary')}</div></header><div class="portable-banner"><span>LOCAL DEMO / SAME GAME ENGINE</span> &nbsp; <span>No dependencies. Simulated models. Full Next.js + real BYOK runtime included in the source.</span></div>`;}
function shell(content){$('#app').innerHTML=header()+content;localize();}
const page=(content)=>`<main class="container page">${content}${footer()}</main>`;
function challengeCard(p){return `<a href="/challenges/${uri(p.slug)}" class="card challenge-card"><div class="flex justify-between items-center"><span class="icon-box ${p.judge==='secret'?'purple':''}">${icon(problemIcon(p),22)}</span>${chip(p.difficulty,p.difficulty==='Hard'?'purple':'green')}</div><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="flex wrap gap-1 mt-2">${p.tags.slice(0,2).map(t=>chip(t)).join('')}</div><div class="card-stats"><div><label>BEST SCORE</label><strong class="accent">${p.stats.bestScore}</strong></div><div><label>BUILDERS</label><strong>${p.stats.participants}</strong></div><div><label>SOLVE RATE</label><strong>${pct(p.stats.solveRate)}</strong></div></div><div class="flex justify-between small dim mt-2"><span>${num(p.constraints.tokenBudget)} energy</span><span>${p.constraints.toolCallLimit} tools / +${p.reward} REP</span></div></a>`;}
function home(d){const boss=d.worldBoss;return `<main class="container"><section class="hero"><div><div class="eyebrow"><span class="live-dot"></span>THE ARENA FOR AI BUILDERS</div><h1>Build AI.<br/><span class="soft">Beat Problems.</span></h1><p class="description">Build prompts, skills, tools and agents.<br/>Challenge real-world problems.<br/>Make AI better together.</p><div class="actions">${link('Start building '+icon('ArrowRight'),'/challenges','primary large')}${link(icon('Trophy')+' Explore the arena','/leaderboard','outline large')}</div><div class="sub-note">YOUR MODEL. YOUR STRATEGY. YOUR NEXT HIGH SCORE.</div></div><div class="hero-lab"><div class="lab-titlebar"><span class="window-dot"></span><span class="window-dot"></span><span class="window-dot"></span><span class="lab-name">precision-engine.workflow</span><span class="push-right accent">SIMULATED RUN</span></div><div class="lab-stage"><span class="mini-link"></span>${[['PROMPT','Extract the signal','Code2','142 tokens'],['MODEL','demo-forge','Cpu','0.32 sec'],['OUTPUT','Valid JSON','Braces','contract passed']].map(([type,name,i,meta])=>`<div class="mini-node ${type==='MODEL'?'model':''}"><div class="mini-type">${icon(i,11)} ${type}</div><div class="mini-name">${name}</div><div class="mini-meta">${meta}</div></div>`).join('')}</div><div class="lab-terminal"><div class="terminal-line"><span class="accent">&gt; workflow.execute(input)</span><span>DONE</span></div><div><span>Deterministic judge</span> &nbsp; / &nbsp; <span>no arbitrary code</span></div><div class="accent">[PASS] output contract validated</div></div><div class="lab-score">${icon('Check',16)}<strong>READY</strong></div></div></section><section class="stats-strip">${[['problems','Live challenges','Target'],['builds','Builds forged','Boxes'],['runs','Agent runs','Activity'],['builders','Builders in the arena','Users']].map(([k,label,i])=>`<div class="stat"><div><strong>${num(d.stats[k])}</strong><label>${label}</label></div>${icon(i)}</div>`).join('')}</section><div class="home-main"><div>${section('The world is your next boss',undefined)}<article class="card boss-card"><div class="boss-visual">${icon('Inbox',65)}</div>${chip('WORLD BOSS','purple')}<h2>Take the inbox to zero.</h2><p>A thousand messy tickets. One sharper agent. Join the community building the perfect support triage workflow.</p><div class="flex justify-between small mb-2"><span class="dim">COMMUNITY SOLVE RATE <span class="small">/ ALL LANES</span></span><b class="purple mono">${pct(boss.stats.solveRate)}</b></div><div class="boss-progress"><span style="width:${boss.stats.solveRate*100}%"></span></div><div class="boss-stats"><div><label>CURRENT BEST</label><strong>${boss.stats.bestScore}<span class="dim"> / 1000</span></strong></div><div><label>BUILDERS</label><strong>${boss.stats.participants}</strong></div><div><label>REWARD</label><strong class="purple">+${boss.reward} REP</strong></div>${link('Challenge boss '+icon('ArrowRight',13),`/challenges/${boss.slug}`,'outline')}</div></article>${section('Pick your next challenge',d.problems.length-1,'/challenges','All missions')}<div class="challenges-grid">${d.problems.filter(p=>!p.worldBoss).map(challengeCard).join('')}</div><div class="card card-pad mt-3 flex justify-between items-center gap-3"><div><div class="eyebrow mb-2">REAL PROBLEMS. BETTER AGENTS.</div><h3>What should AI solve next?</h3><p class="small muted mt-1">Contribute a problem. Give the arena its next mission.</p></div>${link(icon('Plus')+' Propose a problem','/problems/new','outline')}</div></div><aside><section>${section('Top builders',undefined,'/leaderboard')}${d.topBuilders.map((u,i)=>`<a href="/profile/${uri(u.id)}" class="builder-row"><span class="rank-number">${String(i+1).padStart(2,'0')}</span>${avatar(u.name,i)}<div class="grow"><strong>${esc(u.name)}</strong><small>${u.isSeed?'SEEDED BUILDER':'BUILDER'}</small></div><span class="mono accent small">${num(u.reputation)}</span></a>`).join('')}<p class="small dim mt-2">Community reputation / demo population</p></section><section class="mt-4">${section('Popular skills',undefined,'/workshop')}${d.skills.map(s=>`<a class="skill-row" href="/workshop"><span class="icon-box purple">${icon(s.icon,15)}</span><div class="grow"><strong>${esc(s.name)}</strong><small>${s.usageCount} versions equipped</small></div>${icon('ArrowUpRight',13)}</a>`).join('')}</section><section class="mt-4">${section('Failure radar',undefined)}${d.failures.map(f=>`<div class="failure-item"><span class="failure-dot"></span><div><p>${esc(f.reason)}</p><small>${esc(f.creator)} / ${f.tier} ${f.status.replace('_',' ')}</small></div></div>`).join('')}</section></aside></div>${footer()}</main>`;}
function challenges(ps){return page(heading('MISSION SELECT','Reality has no easy mode.','Pick a problem. Forge an agent. Find out how good it really is.',link(icon('Plus')+' Create problem','/problems/new','outline'))+`<div class="flex justify-between gap-3 mb-3 wrap"><div class="search-box" style="position:relative;max-width:360px;width:100%">${icon('Search',15)}<input id="challenge-search" type="search" aria-label="Search challenges" placeholder="Find your next challenge..." style="padding-left:38px"></div><span class="chip green">${ps.length} ACTIVE MISSIONS</span></div><div class="challenges-grid" id="challenge-cards">${ps.map(challengeCard).join('')}</div><div class="mt-3">${laneNote('demo')}</div>`);}
function boardTable(rows){if(!rows.length)return empty('An open podium.','No scores in this lane yet. Submit a build to claim your place.');return `<div class="table-scroll"><table class="leader-table"><thead><tr><th>RANK</th><th>BUILD / PLAYER</th><th>SCORE</th><th>ACCURACY</th><th>COST</th><th>ENERGY</th><th>NODES</th><th>MODEL</th><th>SUBMITTED</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="mono ${r.rank<=3?'accent':''}">${String(r.rank).padStart(2,'0')}</td><td><a href="/builds/${uri(r.buildId)}?version=${uri(r.versionId)}"><strong data-no-locale>${esc(r.title)}</strong><div class="small dim" data-no-locale>${esc(r.creator.name)}${r.creator.isSeed?' / seed':''}</div></a></td><td class="mono accent score-cell">${r.score}</td><td class="mono">${pct(r.accuracy)}</td><td class="mono">${money(r.cost)}</td><td class="mono">${num(r.tokens)}</td><td class="mono">${r.nodes}</td><td><span class="model-tag" data-no-locale>${esc(r.model)}</span></td><td class="small dim">${date(r.createdAt)}</td></tr>`).join('')}</tbody></table></div>`;}
function board(rows,problemId=''){return `<section data-board-problem="${esc(problemId)}"><div class="leaderboard-controls"><div class="tabs">${[['overall','Overall','Trophy'],['cheapest','Cheapest','Zap'],['fastest','Fastest','Timer'],['robust','Robust','Shield'],['minimalist','Minimalist','Boxes']].map(([value,label,i])=>`<button class="tab ${S.board.sort===value?'active':''}" data-action="board-sort" data-value="${value}">${icon(i,12)} ${label}</button>`).join('')}</div><select aria-label="Leaderboard lane" id="board-tier"><option value="demo" ${S.board.tier==='demo'?'selected':''}>Demo / simulated</option><option value="byok" ${S.board.tier==='byok'?'selected':''}>BYOK / unverified</option><option value="verified" ${S.board.tier==='verified'?'selected':''}>Platform / verified</option></select></div><div class="card" id="board-table">${boardTable(rows)}</div><p class="small dim mt-2">Cost, energy and latency are averaged per test case. Cheapest, fastest and minimalist require at least 50% accuracy.</p><div class="mt-2" id="board-note">${laneNote(S.board.tier)}</div></section>`;}
function publicTest(t,i){return `<details class="test-card" ${i===0?'open':''}><summary><span class="mono dim">${String(i+1).padStart(2,'0')}</span><strong>Public test ${i+1}</strong>${chip(t.category)}${icon('ChevronDown',13)}</summary><div class="test-body"><div><div class="eyebrow mb-2">INPUT</div><pre>${esc(t.input)}</pre></div><div><div class="eyebrow mb-2">EXPECTED OUTPUT</div><pre>${esc(JSON.stringify(t.expected,null,2))}</pre></div></div></details>`;}
function challenge(p){S.challenge=p;S.board.problemId=p.id;return page(`<div class="breadcrumb"><a href="/challenges">Challenges</a>${icon('ChevronRight',12)}<span>${esc(p.category)}</span></div>${heading(p.worldBoss?'WORLD BOSS / COMMUNITY MISSION':`MISSION / ${p.difficulty.toUpperCase()}`,p.title,p.description,link(icon('Code2')+' Build an agent',`/builder?problem=${uri(p.slug)}`,'primary large'))}<div class="flex gap-1 wrap mb-3">${p.tags.map(t=>chip(t)).join('')}${chip(p.worldBoss?'WORLD BOSS':'ACTIVE','purple')}</div><div class="detail-grid"><div><div class="card card-pad mission"><div class="eyebrow mb-2">THE MISSION</div><h2>Make the messy world make sense.</h2><p class="muted mt-2">${esc(p.mission)}</p><div class="divider"></div><h3>Win condition</h3><p class="muted mt-2">${esc(p.goal)}</p></div><section class="mt-4">${section('Public test bench',p.publicTests.length)}${p.publicTests.map(publicTest).join('')}</section><section class="card card-pad mt-3"><div class="flex items-center gap-2 mb-3">${icon('Lock')}<h3>The sealed suite</h3></div><p class="small muted mb-3">Hidden inputs, expected answers, and per-case output never leave the server API.</p><div class="hidden-tests">${Object.entries(p.hiddenCounts).map(([k,v])=>`<div class="hidden-test-counter"><strong>${v}</strong><span>${k}</span></div>`).join('')}</div></section><section class="mt-4">${section('Mission leaderboard',undefined)}${board(p.leaderboard,p.id)}</section><section class="card card-pad mt-4"><div class="eyebrow mb-2">FAILURE HUNTER</div><h2>Can you break the #1 agent?</h2><p class="small muted mt-2 mb-3">The server tests the top submitted public build, using your provider, never its creator's key. Objective contract failures earn reputation; semantic disputes await review.</p>${S.user?`<form id="failure-form"><input type="hidden" name="problemId" value="${esc(p.id)}">${textField('Your failure input','input','','required maxlength="4000" placeholder="Try an edge case the agent may have missed..."')}${textField('Why should this fail?','reason','','required minlength="8" maxlength="1000"')}<div class="field"><label class="label" for="failure-provider">Run provider</label><select id="failure-provider" name="providerId"><option value="demo">Demo simulator / no API cost</option></select></div><button class="button primary" type="submit">${icon('Target')} Hunt failure</button></form><div id="failure-result" class="mt-2" aria-live="polite"></div>`:link('Sign in to hunt failures','/login?next='+uri(location.pathname),'outline')}${p.failures.length?`<div class="divider"></div>${p.failures.map(f=>`<div class="failure-item"><span class="failure-dot"></span><div><p>${esc(f.reason)}</p><small>${esc(f.creator)} / ${f.status} / ${f.tier}</small></div></div>`).join('')}`:''}</section></div><aside class="detail-sidebar stack"><div class="card card-pad"><div class="eyebrow mb-3">MISSION CONSTRAINTS / PER CASE</div><dl class="spec-list"><div><dt>Token budget</dt><dd>${num(p.constraints.tokenBudget)}</dd></div><div><dt>Tool calls</dt><dd>${p.constraints.toolCallLimit} max</dd></div><div><dt>Cost cap</dt><dd>${money(p.constraints.maxCost)}</dd></div><div><dt>Latency cap</dt><dd>${time(p.constraints.maxLatencyMs)}</dd></div><div><dt>Judge</dt><dd>${esc(p.judge)} / deterministic</dd></div><div><dt>Reward</dt><dd class="accent">+${p.reward} REP</dd></div></dl><div class="divider"></div>${link(icon('Play')+' Enter the forge',`/builder?problem=${uri(p.slug)}`,'primary w-full')}<p class="helper center mt-2">No API key needed for Demo mode.</p></div><div class="card card-pad"><div class="eyebrow mb-3">THE SCORING SYSTEM</div>${[['Accuracy',45],['Robustness',20],['Security',15],['Efficiency',10],['Elegance',10]].map(([name,weight])=>`<div class="flex justify-between small mt-1"><span class="muted">${name}</span><span class="mono">${weight}%</span></div>`).join('')}<p class="helper mt-3">A fixed formula. Never an LLM's opinion.</p></div>${laneNote('demo')}</aside></div>`);}
function workshop(skills,tools){return page(heading('SKILL DECK / CONTROLLED EQUIPMENT','Give your agent an edge.','Skills change behavior. Tools extend capability. Equip only what your strategy needs.')+`<div class="grid-3">${skills.map(s=>`<article class="card skill-card"><div class="flex justify-between"><span class="icon-box purple">${icon(s.icon,22)}</span>${chip('SKILL','purple')}</div><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="skill-effect">${esc(s.effect)}</div><footer><span>${num(s.usageCount)} BUILDS / ${s.successRate===null?'NO RUNS':pct(s.successRate)+' PASS'}</span><a href="/builder?problem=messy-json-extractor&skill=${s.id}" class="section-link accent">Equip ${icon('Plus',12)}</a></footer><p class="helper mt-1">${s.simulated?'Statistics include simulated submissions.':'Statistics include BYOK submissions.'} By ${esc(s.author)}.</p></article>`).join('')}</div><section class="mt-4">${section('Registered tools',tools.length)}<div class="grid-3">${tools.map(t=>`<article class="card card-pad"><div class="flex items-center gap-2 mb-2"><span class="icon-box">${icon(t.icon)}</span><h3>${esc(t.name)}</h3></div><p class="small muted">${esc(t.description)}</p><span class="chip green mt-2">CONTROLLED / NO SHELL</span></article>`).join('')}</div></section><div class="callout mt-3">${icon('ShieldCheck')} Arbitrary code upload, shell commands, unrestricted HTTP tools and server file access are deliberately disabled.</div>`);}
function providers(p){S.providers=p;return page(heading('BYOK / YOUR ENGINE','Power your own build.','Bring an OpenAI-compatible endpoint. Credentials are encrypted at rest and never copied into a fork.')+`<div class="callout purple mb-3">${icon('Activity')} This offline runtime can save encrypted credentials, but cannot call real models. Start the included Next.js runtime for Vercel AI SDK execution. There is no silent fallback to simulation.</div><div class="detail-grid"><div class="card card-pad"><h2 class="mb-3">Add a provider</h2><form id="provider-form">${field('Provider name','name','','required maxlength="60" placeholder="My OpenRouter"')}${field('Base URL','baseUrl','https://openrouter.ai/api/v1','required type="url" maxlength="300"')}${field('Model ID','modelId','','required maxlength="160" placeholder="provider/model-name"')}${field('API key','apiKey','','required type="password" minlength="16" maxlength="512" autocomplete="off" placeholder="Your private API key"')}<div class="form-grid">${field('Input price / 1M tokens (optional)','inputPrice','','type="number" min="0" max="10000" step="any" placeholder="unknown"')}${field('Output price / 1M tokens (optional)','outputPrice','','type="number" min="0" max="10000" step="any" placeholder="unknown"')}</div><p class="helper mb-3">Missing prices remain unknown. No invented cost estimates. Only HTTPS endpoints on the administrator's host allowlist are accepted.</p><button type="submit" class="button primary">${icon('Lock')} Encrypt & save credential</button></form></div><aside class="stack"><div class="card"><div class="card-header"><h3>Saved engines</h3>${chip(String(p.credentials.length))}</div>${p.credentials.length?p.credentials.map(c=>`<div class="provider-card"><span class="icon-box purple">${icon('Cpu')}</span><div class="grow"><h3 data-no-locale>${esc(c.name)}</h3><div class="provider-url" data-no-locale>${esc(c.baseUrl)}</div><code data-no-locale>${esc(c.keyMask)}</code><div class="small muted mt-1" data-no-locale>${esc(c.modelId)}</div><div class="small dim mt-1">${c.inputPrice===null||c.outputPrice===null?'Cost: unknown':`Input $${c.inputPrice} / Output $${c.outputPrice} per 1M`}</div></div>${button(icon('Trash2'),'delete-provider','ghost icon',`data-id="${esc(c.id)}" aria-label="Delete ${esc(c.name)}"`)}</div>`).join(''):empty('No private engines yet.','The Demo engine is ready to play without a key.')}</div><div class="card card-pad"><h3 class="mb-2">A real trust boundary.</h3><p class="small muted">AES-256-GCM authenticated encryption. Owner-only credential access. No raw provider exceptions, redirects, private-network requests, or credential-bearing public APIs.</p><div class="divider"></div><div class="eyebrow mb-2">ALLOWED HOSTS</div><pre class="small muted">${esc(p.allowedHosts.join('\n'))}</pre><p class="helper mt-2">Configure additional hosts in the full runtime's server environment. Never expose the local demo to the internet.</p></div></aside></div>`);}
function createProblem(){return page(heading('COMMUNITY MISSIONS','Give the arena a real problem.','Your proposal enters a pending queue. It is not automatically published as a challenge.')+`<form id="problem-form" class="card card-pad" style="max-width:850px">${field('Problem title','title','','required minlength="5" maxlength="100" placeholder="What should an agent solve?"')}${textField('Describe the problem','description','','required minlength="20" maxlength="3000"')}${textField('Why this matters','why','','required minlength="10" maxlength="2000"')}<div class="form-grid">${textField('Example input','exampleInput','','required maxlength="4000"')}${textField('Expected output','expectedOutput','','required maxlength="4000"')}</div><div class="field"><label class="label" for="category">Category</label><select name="category" id="category"><option>Productivity</option><option>Data extraction</option><option>Security</option><option>Customer support</option><option>Other</option></select></div><button class="button primary" type="submit">${icon('Send')} Submit for review</button><div id="problem-result" class="mt-3" aria-live="polite"></div></form>`);}
function profile(p){return page(`<div class="profile-hero">${avatar(p.name,0,true)}<div><div class="eyebrow">${p.isSeed?'SEEDED BUILDER':'PLAYER PROFILE'}</div><h1 data-no-locale>${esc(p.name)}</h1><p class="small muted">Forging since ${date(p.createdAt)} &nbsp; / &nbsp; ${p.builds.length} builds</p></div>${p.owner?link(icon('Settings')+' Provider settings','/providers','outline push-right'):''}</div><div class="profile-stats">${[['ELO / BENCHMARK RATING',p.elo],['REPUTATION',p.reputation],['GLOBAL RANK',`#${p.rank}`]].map(([name,value])=>`<div class="profile-stat"><div class="eyebrow">${name}</div><strong class="accent">${value}</strong></div>`).join('')}</div><p class="small dim">ELO is an MVP benchmark rating: 1000 + best verified score. Seed profiles have synthetic ratings; it is not a head-to-head chess Elo system.</p><div class="badge-grid">${p.badges.map(b=>`<div class="badge-card ${b.earned?'earned':''}" title="${esc(b.description)}">${icon(b.icon,25)}<strong>${esc(b.name)}</strong><small>${b.earned?'UNLOCKED':'LOCKED'}</small></div>`).join('')}</div><div class="detail-grid"><div class="card card-pad">${section('Build collection',p.builds.length)}${p.builds.length?p.builds.map(b=>`<a href="/builds/${uri(b.id)}" class="profile-build-row"><div><strong data-no-locale>${esc(b.title)}</strong><div class="small dim">${b.visibility} prompt / ${date(b.updatedAt)}</div></div><span class="mono accent">${b.bestScore||'--'} ${icon('ArrowUpRight',12)}</span></a>`).join(''):empty('Your forge is waiting.','Take your first idea into a challenge.',link('Choose a mission','/challenges','primary'))}${p.problems.length?`<div class="divider"></div>${section('Problem proposals',p.problems.length)}${p.problems.map(x=>`<div class="profile-build-row"><strong data-no-locale>${esc(x.title)}</strong>${chip(x.status,'amber')}</div>`).join('')}`:''}</div><aside class="stack"><div class="card card-pad"><div class="eyebrow mb-3">CONTRIBUTIONS</div><dl class="spec-list"><div><dt>Failure candidates</dt><dd>${p.failureCount}</dd></div><div><dt>Forks created</dt><dd>${p.forkCount}</dd></div><div><dt>Problems proposed</dt><dd>${p.problems.length}</dd></div></dl></div><div class="card card-pad"><h3 class="mb-2">Reputation log</h3>${p.reputationHistory.length?p.reputationHistory.map(r=>`<div class="flex justify-between small mt-1"><span class="muted" data-no-locale>${esc(r.reason)}</span><span class="mono accent">+${r.points}</span></div>`).join(''):'<p class="small dim">Save, submit, remix, and hunt failures to earn your place.</p>'}</div></aside></div>`);}
function grades(score){return `<div class="grade-list">${['accuracy','robustness','security','efficiency','elegance'].map(k=>`<div class="grade-row"><span class="grade-label">${k[0].toUpperCase()+k.slice(1)}</span><div class="grade-bar"><span style="width:${Math.max(0,Math.min(1,score[k]))*100}%"></span></div><strong>${esc(score.grades?.[k]||(score[k]>=.97?'SS':score[k]>=.9?'S':score[k]>=.8?'A':score[k]>=.65?'B':'C'))}</strong></div>`).join('')}</div>`;}
function buildDetail(b){const best=b.submissions.filter(s=>s.versionId===b.version.id).sort((a,c)=>c.score-a.score)[0];S.detail=b;return page(`<div class="breadcrumb"><a href="/challenges/${uri(b.problem.slug)}">${esc(b.problem.title)}</a>${icon('ChevronRight',12)}<span>Build #${esc(b.id.slice(0,8))}</span></div>${heading(`BUILD ASSET / VERSION ${b.version.revision}`,b.title,`Forged by ${b.creator.name}`,`<div class="flex gap-2">${b.owner?link(icon('Code2')+' Edit version',`/builder?build=${uri(b.id)}&version=${uri(b.version.id)}`,'outline'):''}${button(icon('GitFork')+' Fork / Remix','fork','primary',`data-id="${esc(b.id)}" data-version="${esc(b.version.id)}" ${b.canFork?'':'disabled'}`)}</div>`)}<div class="flex gap-2 mb-3">${chip(b.promptVisible?'PROMPT VISIBLE':'SECRET PROMPT',b.promptVisible?'green':'purple')}${chip(b.forkCount+' FORKS')}${best?chip(best.tier.toUpperCase()+' LANE','purple'):''}</div><div class="detail-grid"><div><section class="card card-pad">${section('Workflow blueprint',b.workflow.nodes.length)}${!b.promptVisible?'<div class="callout purple small">Private configurations are redacted. This build cannot be forked by other players.</div>':''}<div class="build-graph-preview portable-preview"><div class="flow-simple"><div class="flow-content" style="min-width:1250px;min-height:270px;transform:scale(.85)">${flowHtml(b.workflow,false)}</div></div></div></section>${b.promptVisible?b.workflow.nodes.filter(n=>n.kind==='prompt').map(n=>`<section class="card card-pad mt-3"><div class="flex justify-between mb-3"><h3 data-no-locale>${esc(n.label)}</h3>${chip(Math.ceil((n.config.systemPrompt||'').length/4)+' TOKENS / EST.')}</div><pre>${esc(n.config.systemPrompt)}</pre><div class="divider"></div><div class="eyebrow mb-2">USER TEMPLATE</div><pre class="muted">${esc(n.config.userTemplate)}</pre></section>`).join(''):''}<section class="card card-pad mt-3"><h3 class="mb-2">Version history</h3>${b.history.map(v=>`<a href="/builds/${uri(b.id)}?version=${uri(v.id)}" class="profile-build-row"><span class="small" data-no-locale>v${v.revision} / ${esc(v.title)}</span><span class="small dim">${date(v.createdAt)} ${icon('ArrowUpRight',12)}</span></a>`).join('')}</section></div><aside class="stack"><div class="card card-pad"><div class="eyebrow mb-3">BEST SCORE / THIS VERSION</div>${best?`<div class="score-large">${best.score}<small> / 1000</small></div><div class="divider"></div>${grades(best)}<div class="divider"></div><dl class="spec-list"><div><dt>Model</dt><dd class="small">${esc(best.model)}</dd></div><div><dt>Energy / case</dt><dd>${num(best.tokens)}</dd></div><div><dt>Cost / case</dt><dd>${money(best.cost)}</dd></div><div><dt>Latency / case</dt><dd>${time(best.latency)}</dd></div><div><dt>Workflow nodes</dt><dd>${best.nodes}</dd></div></dl>`:'<p class="small muted">No hidden submission for this version yet.</p>'}</div><div class="callout small">${icon('GitFork')} A remix copies the selected version, never its API key or private credential reference.</div>${b.parentBuildId?link('View parent build '+icon('ArrowUpRight'),'/builds/'+uri(b.parentBuildId),'outline'):''}</aside></div>`);}
function login(){return `<main class="auth-shell"><section class="auth-story"><div class="eyebrow">YOUR NEXT BUILD STARTS HERE</div><h1>Don't just<br/>use AI.<br/><span class="accent">Forge it.</span></h1><p>Every problem is a level. Every failure is a clue. Every fork is the beginning of something better.</p><div class="quote">PROMPT &rarr; SKILL &rarr; TOOL &rarr; AGENT<br/>Your ideas. Your engine. Your place in the arena.</div></section><section class="auth-form"><h2>${S.register?'Join the builders.':'Back to the forge.'}</h2><p>${S.register?'Create an account and start your first build.':'Sign in to run, submit and remix.'}</p><form id="auth-form">${S.register?field('Builder name','name','','required minlength="2" maxlength="60" autocomplete="nickname" placeholder="your.handle"'):''}${field('Email','email','','required type="email" autocomplete="email" placeholder="you@example.com"')}${field('Password','password','','required type="password" minlength="10" maxlength="128" autocomplete="'+(S.register?'new-password':'current-password')+'" placeholder="At least 10 characters"')}<button class="button primary large w-full" type="submit">${S.register?'Create account':'Sign in'} ${icon('ArrowRight')}</button><div id="auth-error" class="error-text" role="alert"></div></form><div class="auth-separator">OR CONTINUE WITH</div>${button(icon('Github')+' GitHub / full runtime','noop','outline w-full large','disabled title="GitHub OAuth is available in the Next.js runtime after configuration"')}${!S.register?button(icon('Sparkles')+' Use seeded demo account','demo-login','ghost w-full mt-2'):''}<p class="small muted center mt-3">${S.register?'Already a builder?':'New to the arena?'} ${button(S.register?'Sign in':'Create account','toggle-register','ghost small accent')}</p><p class="small dim center mt-3">Local demo authentication uses salted scrypt hashes and HttpOnly sessions. The full runtime uses Better Auth.</p></section></main>`;}
const kinds={input:['Input','ArrowDownToLine'],prompt:['Prompt','Code2'],model:['Model','Cpu'],skill:['Skill','Sparkles'],tool:['Tool','Wrench'],validator:['Validator','ShieldCheck'],output:['Output','ArrowUpFromLine']};
const defaultSchema={type:'object',additionalProperties:false,required:['name','age','city'],properties:{name:{type:['string','null']},age:{type:['number','null']},city:{type:['string','null']}}};
const routeLabels=['billing','bug','account','refund','other'];
function nodeMeta(n){return n.kind==='model'?n.config.modelId||'Choose an engine':n.kind==='prompt'?`~${Math.ceil((n.config.systemPrompt||'').length/4)} tokens / estimate`:n.kind==='skill'?S.skills.find(s=>s.id===n.config.skillId)?.name||n.config.skillId||'Equip a skill':n.kind==='tool'?S.tools.find(t=>t.id===n.config.toolId)?.name||n.config.toolId||'Registered tool':n.kind==='validator'?'Output contract':n.kind==='input'?'{{input}}':'Final response';}
function wirePath(w,edge){const a=w.nodes.find(n=>n.id===edge.source),b=w.nodes.find(n=>n.id===edge.target);if(!a||!b)return '';const x1=a.x+186,y1=a.y+49,x2=b.x,y2=b.y+49,offset=Math.max(50,Math.abs(x2-x1)*.5);return `M${x1} ${y1}C${x1+offset} ${y1},${x2-offset} ${y2},${x2} ${y2}`;}
function flowHtml(w,interactive=true){return `<svg class="connections" aria-hidden="true">${w.edges.map(edge=>`<path d="${wirePath(w,edge)}" stroke="#71865a" stroke-width="1.7" fill="none"/>${interactive?`<path d="${wirePath(w,edge)}" class="wire-delete" fill="none" data-action="delete-edge" data-id="${esc(edge.id)}"><title>Click to remove this connection</title></path>`:''}`).join('')}</svg>${w.nodes.map(n=>`<div class="forge-node ${n.kind} ${interactive&&S.builder?.selected===n.id?'selected':''}" data-node="${esc(n.id)}" style="left:${Number(n.x)}px;top:${Number(n.y)}px" ${interactive?'tabindex="0"':''}>${interactive&&n.kind!=='input'?`<span class="port in" role="button" tabindex="0" aria-label="Connect to ${esc(n.label)}" data-action="connect-target" data-id="${esc(n.id)}"></span>`:''}<div class="node-top">${icon(kinds[n.kind]?.[1]||'Boxes',12)}${esc(kinds[n.kind]?.[0]||n.kind)}<span class="node-state">${interactive&&S.builder?.states[n.id]==='done'?icon('Check',10):''}</span></div><div class="node-content"><div class="node-title">${esc(n.label)}</div><div class="node-meta${n.kind==='model'?' user-content':''}"${n.kind==='model'?' data-no-locale':''}>${esc(nodeMeta(n))}</div></div>${interactive&&n.kind!=='output'?`<span class="port out" role="button" tabindex="0" aria-label="Connect from ${esc(n.label)}" data-action="connect-source" data-id="${esc(n.id)}"></span>`:''}</div>`).join('')}`;}
function codeEditor(label,key,value,rows=7){return `<div class="field"><div class="flex justify-between items-center mb-1"><label class="label" for="node-${key}">${esc(label)}</label>${button(icon('Copy',11),'copy-config','ghost small',`data-key="${key}" aria-label="Copy ${esc(label)}"`)}</div><div class="code-editor"><div class="line-numbers" aria-hidden="true">${Array.from({length:Math.max(3,String(value).split('\n').length)},(_,i)=>`<span>${i+1}</span>`).join('')}</div><textarea id="node-${key}" data-config="${key}" rows="${rows}" spellcheck="false" maxlength="8000">${esc(value)}</textarea></div><div class="prompt-footer"><span id="count-${key}">${String(value).length} chars</span><span id="tokens-${key}">~${Math.ceil(new TextEncoder().encode(String(value)).length/4)} tokens / est.</span></div></div>`;}
const option=(id,label,current)=>`<option value="${esc(id)}" ${id===current?'selected':''}>${esc(label)}</option>`;
const configInput=(label,key,value,extra='')=>`<div class="field"><label class="label" for="node-${key}">${label}</label><input id="node-${key}" data-config="${key}" value="${esc(value)}" ${extra}></div>`;
function inspectorHtml(){const b=S.builder,n=b.w.nodes.find(n=>n.id===b.selected);if(!n)return `<div class="config-header">NODE CONFIGURATION</div><div class="build-inspector-empty">${icon('Settings',28)}<p class="mt-2">Select a node to tune your strategy.<br/>Click an output port, then an input port to connect nodes.</p></div>`;const c=n.config;let content='';
 if(n.kind==='prompt')content=codeEditor('System prompt','systemPrompt',c.systemPrompt||'')+codeEditor('User template','userTemplate',c.userTemplate||'',3)+`<p class="helper">Variables: {{input}} and {{previous}}. Edges determine which previous output is used.</p>${button(icon('RotateCcw',12)+' Reset starter','reset-prompt','ghost small mt-2')}`;
 if(n.kind==='model')content=`<div class="field"><label class="label" for="node-provider">Provider</label><select id="node-provider" data-config="credentialId">${option('demo','Demo simulator / no API cost',c.credentialId)}${(S.providers?.credentials||[]).map(p=>option(p.id,`${p.name} / ${p.keyMask}`,c.credentialId)).join('')}</select></div>${configInput('Model ID','modelId',c.modelId||'',`maxlength="160" ${c.credentialId==='demo'?'disabled':''}`)}<div class="form-grid">${configInput('Output token cap','maxTokens',c.maxTokens||512,'type="number" min="16" max="8192"')}${configInput('Temperature','temperature',c.temperature??0,'type="number" min="0" max="2" step=".1"')}</div><div class="callout small purple">Simulation is free and deliberately imperfect. Real providers require the full Next.js runtime.</div><a href="/providers" class="section-link mt-3">${icon('Lock',12)} Manage encrypted keys</a>`;
 if(n.kind==='skill')content=`<div class="field"><label class="label" for="node-skill">Equipped skill</label><select id="node-skill" data-config="skillId">${S.skills.map(s=>option(s.id,s.name,c.skillId)).join('')}</select></div><p class="helper mb-3">${esc(S.skills.find(s=>s.id===c.skillId)?.description)}</p>${c.skillId==='structured'?codeEditor('JSON Schema','schema',JSON.stringify(c.schema||defaultSchema,null,2),9):''}${c.skillId==='concise'?configInput('Maximum output characters','maxLength',c.maxLength||300,'type="number" min="1" max="8000"'):''}<div class="callout small">Skills before the Model affect its behavior. Reflection and Retry may add one bounded model call.</div>`;
 if(n.kind==='tool')content=`<div class="field"><label class="label" for="node-tool">Registered tool</label><select id="node-tool" data-config="toolId">${S.tools.map(t=>option(t.id,t.name,c.toolId)).join('')}</select></div><p class="helper mb-3">${esc(S.tools.find(t=>t.id===c.toolId)?.description)}</p>${c.toolId==='json-validator'?codeEditor('JSON Schema','schema',JSON.stringify(c.schema||defaultSchema,null,2),9):c.toolId==='calculator'?configInput('Expression / blank uses previous output','expression',c.expression||'','maxlength="300"'):c.toolId==='text-search'?configInput('Search query','query',c.query||'','maxlength="1000"'):c.toolId==='string-matcher'?configInput('Text to match','match',c.match||'','maxlength="1000"'):''}${c.toolId==='string-matcher'?`<div class="field"><label class="label">Match mode</label><select data-config="mode">${option('contains','Contains',c.mode||'contains')}${option('exact','Exact',c.mode)}</select></div>`:''}<div class="callout small">Before Model: equips AI tool calling. After Model: executes on the previous output. No arbitrary code.</div>`;
 if(n.kind==='validator')content=`<div class="field"><label class="label" for="node-format">Output contract</label><select id="node-format" data-config="format">${option('json','JSON Schema',c.format||'json')}${option('enum','Exact enum',c.format)}${option('text','Nonempty text',c.format)}</select></div>${(c.format||'json')==='json'?codeEditor('JSON Schema','schema',JSON.stringify(c.schema||defaultSchema,null,2),9):c.format==='enum'?codeEditor('Allowed values / one per line','values',(c.values||routeLabels).join('\n'),5):''}<p class="helper">A failed validation fails the case. Retry a failed model contract with the Retry skill before the Model.</p>`;
 if(n.kind==='input')content='<div class="callout small">The server supplies one challenge input per test case. Hidden test contents are not editable or visible in this browser.</div>';
 if(n.kind==='output')content='<div class="callout small">The final response goes to the deterministic judge. Every path to Output must include a Model.</div>';
 return `<div class="config-header">${icon(kinds[n.kind][1])}<strong>${esc(kinds[n.kind][0])} configuration</strong><span class="mono dim small push-right">v${b.version||1}</span></div><div class="config-body"><div class="field"><label class="label" for="node-label">Node name</label><input id="node-label" value="${esc(n.label)}" maxlength="80"></div>${content}<div id="config-error" class="error-text"></div><div class="node-actions mt-3">${button(icon('Copy',12)+' Duplicate','duplicate-node','outline small')}${button(icon('Trash2',12)+' Delete','delete-node','ghost small danger')}</div><p class="helper mt-2">Deleting a node removes its connections. Reconnect the path before saving.</p></div>`;
}
function builderHtml(){const b=S.builder,p=b.problem;return `<main class="builder-page"><div class="builder-toolbar"><div class="builder-title"><div class="breadcrumb"><a href="/challenges/${uri(p.slug)}">${esc(p.title)}</a>${icon('ChevronRight',10)}<span>AGENT BUILDER</span></div><div class="flex items-center gap-2"><input id="build-title" aria-label="Build name" value="${esc(b.title)}" maxlength="80"><span class="chip" id="version-label">v${b.version||1}${b.dirty?' *':''}</span></div></div><div class="toolbar-actions"><select id="build-visibility" aria-label="Build visibility">${option('private','Secret prompt',b.visibility)}${option('public','Public prompt',b.visibility)}</select>${button(icon('Download'),'export','ghost icon','title="Export workflow JSON" aria-label="Export workflow"')}${button(icon('Save',14)+' Save','save-build','outline','id="save-build"')}${button(icon('Play',14)+' Run public tests','run-public','outline','id="run-public"')}${button(icon('Send',14)+' Submit','run-hidden','primary','id="run-hidden"')}</div></div><div id="builder-error" class="builder-error" aria-live="polite"></div><div class="builder-grid"><aside class="palette"><div class="panel-eyebrow">COMPONENTS <span class="dim">/ 7</span></div>${Object.entries(kinds).map(([kind,[label,i]])=>`<button draggable="true" class="palette-item" data-action="add-node" data-kind="${kind}">${icon(i,14)}<span>${label}</span><span class="plus">+</span></button>`).join('')}<div class="divider"></div><div class="panel-eyebrow">QUICK EQUIP</div>${S.skills.map(s=>`<button class="equip-card" data-action="equip" data-id="${s.id}" title="${esc(s.description)}">${icon(s.icon,12)}<span>${esc(s.name)}</span><span class="push-right">+</span></button>`).join('')}<p class="helper">Click a port to connect.<br/>Click a wire to remove it.<br/>Drag nodes to reposition.<br/>All paths need a Model.</p><div class="palette-footer">${icon('ShieldCheck',12)} Controlled tools only</div></aside><section class="canvas-panel"><div class="canvas-toolbar"><span id="canvas-status">WORKFLOW CANVAS / ${b.w.nodes.length} NODES</span><div class="flex gap-1" style="pointer-events:auto">${button('Fit','canvas-fit','small ghost')}${button('-','zoom-out','small ghost','aria-label="Zoom out"')}${button('+','zoom-in','small ghost','aria-label="Zoom in"')}</div><span id="connect-notice" class="connecting-notice hidden"></span></div><div id="flow-viewport" class="flow-simple" aria-label="Workflow canvas"><div id="flow-content" class="flow-content"></div></div><div class="canvas-shortcuts">${num(p.constraints.tokenBudget)} ENERGY MAX / ${p.constraints.toolCallLimit} TOOL CALLS</div></section><aside class="config-panel" id="inspector">${inspectorHtml()}</aside><section class="run-console"><div class="console-header">${icon('Terminal',14)}${[['results','TEST RESULTS'],['trace','EXECUTION TRACE'],['energy','ENERGY']].map(([id,name])=>`<button class="console-tab ${id===b.tab?'active':''}" data-action="console-tab" data-id="${id}">${name}</button>`).join('')}<span class="push-right portable-builder-status" id="run-status">READY</span></div><div id="run-progress" class="run-progress hidden"><span></span></div><div id="console-body" class="console-body" aria-live="polite"></div></section></div></main>`;}
function paintFlow(){const b=S.builder,view=$('#flow-viewport'),content=$('#flow-content');if(!b||!view||!content)return;const maxX=Math.max(1050,...b.w.nodes.map(n=>n.x+235)),maxY=Math.max(400,...b.w.nodes.map(n=>n.y+160));const fit=Math.min(1,(view.clientWidth-20)/maxX);b.scale=b.zoom||Math.max(.35,fit);const scale=b.scale;content.style.cssText=`min-width:0;min-height:0;width:${maxX*scale}px;height:${Math.max(view.clientHeight,maxY*scale)}px;`;content.innerHTML=`<div id="flow-plane" style="position:relative;transform:scale(${scale});transform-origin:0 0;width:${maxX}px;height:${maxY}px">${flowHtml(b.w)}</div>`;for(const [id,state] of Object.entries(b.states))$(`[data-node="${CSS.escape(id)}"]`,view)?.classList.add(state);localize();}
function markDirty(){const b=S.builder;if(!b)return;b.dirty=true;const label=$('#version-label');if(label)label.textContent=`v${b.version||1} *`;const status=$('#canvas-status');if(status)status.textContent=`WORKFLOW CANVAS / ${b.w.nodes.length} NODES`;}
function paintInspector(){if($('#inspector')){$('#inspector').innerHTML=inspectorHtml();localize();}}
function selectNode(id){S.builder.selected=id;document.querySelectorAll('#flow-plane [data-node]').forEach(n=>n.classList.toggle('selected',n.dataset.node===id));paintInspector();}
function defaultConfig(kind,skill){return kind==='prompt'?{systemPrompt:'Transform the input. Return only the final answer.',userTemplate:'{{previous}}'}:kind==='model'?{credentialId:'demo',modelId:'demo-forge',maxTokens:512,temperature:0}:kind==='skill'?{skillId:skill||'structured',...(!skill||skill==='structured'?{schema:structuredClone(defaultSchema)}:{})}:kind==='tool'?{toolId:'json-validator'}:kind==='validator'?{format:'json',schema:structuredClone(defaultSchema)}:{};}
function addNode(kind,skill,position){const b=S.builder;if(b.w.nodes.length>=24){toast('A workflow supports at most 24 nodes.',true);return;}const n={id:crypto.randomUUID(),kind,label:skill?S.skills.find(s=>s.id===skill).name:kinds[kind][0],x:position?.x||320,y:position?.y||310,config:defaultConfig(kind,skill)};if(skill){const model=b.w.nodes.find(n=>n.kind==='model'),incoming=model&&b.w.edges.find(e=>e.target===model.id);if(model&&incoming){n.x=model.x;n.y=model.y;const threshold=model.x;b.w.nodes.forEach(x=>{if(x.x>=threshold)x.x+=240;});b.w.edges=b.w.edges.filter(e=>e.id!==incoming.id);b.w.edges.push({id:crypto.randomUUID(),source:incoming.source,target:n.id},{id:crypto.randomUUID(),source:n.id,target:model.id});}}b.w.nodes.push(n);b.selected=n.id;b.zoom=null;markDirty();paintFlow();paintInspector();}
function removeSelected(){const b=S.builder;if(!b?.selected)return;const id=b.selected;b.w.nodes=b.w.nodes.filter(n=>n.id!==id);b.w.edges=b.w.edges.filter(e=>e.source!==id&&e.target!==id);b.selected=null;markDirty();paintFlow();paintInspector();}
function connectNode(source,target){const b=S.builder;if(source===target){toast('A node cannot connect to itself.',true);return;}if(b.w.edges.some(e=>e.source===source&&e.target===target)){toast('These nodes are already connected.');return;}b.w.edges.push({id:crypto.randomUUID(),source,target});b.connecting=null;$('#connect-notice')?.classList.add('hidden');markDirty();paintFlow();toast('Connection added. The server checks that the graph is acyclic.');}
function consoleHtml(){const b=S.builder;if(b.tab==='trace')return `<div class="console-traces">${b.traces.length?b.traces.map((t,i)=>`<div class="trace-line"><span class="dim">${String(i+1).padStart(3,'0')}</span><span class="${t.state==='failed'?'danger':'accent'}">${t.state==='running'?'RUN ':t.state==='done'?'DONE':'FAIL'}</span><span class="node-label">${esc(t.label)}</span><span class="dim">case ${t.caseNumber}</span><span class="trace-token">${t.tokens===undefined?'':num(t.tokens)+' tokens'} ${t.latency===undefined?'':'/ '+time(t.latency)}</span></div>`).join(''):`<p class="dim">${b.kind==='hidden'?'Hidden execution traces stay server-side.':'Run public tests to see the workflow come alive.'}</p>`}</div>`;
 const s=b.summary;let html='';if(s){const m=s.metrics;html=`<div class="console-score result-flash"><div><div class="eyebrow">${b.kind==='hidden'?'ARENA SCORE':'PRACTICE SCORE'}</div><div class="score-large">${s.score.total}<small>/1000</small></div><div class="score-verdict"><strong class="accent">${s.passed}</strong> / ${s.total} tests passed</div>${b.kind==='hidden'?`<a class="section-link mt-2" href="/leaderboard?problem=${uri(b.problem.id)}&tier=${s.tier}">View leaderboard ${icon('ArrowUpRight',12)}</a>`:''}</div>${grades(s.score)}<div class="energy-breakdown"><div><label>Prompt</label><span>${num(m.inputTokens)} tokens</span></div><div><label>Reasoning</label><span>${num(m.reasoningTokens)} tokens</span></div><div><label>Visible output</label><span>${num(Math.max(0,m.outputTokens-m.reasoningTokens))} tokens</span></div><div><label>Total energy</label><b class="accent">${num(m.inputTokens+m.outputTokens)}</b></div><div><label>Tool calls / all cases</label><span>${m.toolCalls}</span></div><div><label>${s.tier==='demo'?'Simulated':'Estimated'} cost</label><span>${money(m.cost)}</span></div><div><label>Summed execution time</label><span>${time(m.latency)}</span></div></div></div><div class="divider"></div>`;}
 if(b.tab==='energy')return html||'<div class="console-welcome">Run a test suite to measure energy, cost, and latency.</div>';
 if(b.kind==='public')html+=b.cases.map((c,i)=>`<details class="case-result" ${!c.passed?'open':''}><summary><span class="result-status ${c.passed?'accent':'danger'}">${c.passed?'PASS':'FAIL'}</span><span>Case ${i+1} / ${esc(c.category)}</span><span class="push-right mono dim">${time(c.latency)} / ${num(c.inputTokens+c.outputTokens)} tokens</span>${icon('ChevronDown',12)}</summary><div class="case-details"><div style="grid-column:1/3"><div class="eyebrow">INPUT</div><pre>${esc(c.input)}</pre></div><div><div class="eyebrow">EXPECTED</div><pre>${esc(JSON.stringify(c.expected,null,2))}</pre></div><div><div class="eyebrow">ACTUAL</div><pre>${esc(c.actual)}</pre></div><div class="case-stats"><span>INPUT ${c.inputTokens}</span><span>OUTPUT ${c.outputTokens}</span><span>COST ${money(c.cost)}</span><span>${esc(c.failureType||'Contract passed')}</span></div></div></details>`).join('');
 if(b.kind==='hidden'&&(s||b.running))html+=`<div class="callout small">${icon('Lock',13)}${b.running?'The server is judging the sealed suite.':'Hidden inputs, expected answers, actual outputs, and traces are not returned.'}</div>${s?`<div class="flex gap-2 mt-2">${Object.entries(s.failures).map(([name,count])=>chip(`${name}: ${count}`)).join('')||chip('ALL CONTRACTS PASSED','green')}</div><div class="mt-2">${laneNote(s.tier)}</div>`:''}`;
 if(!s&&!b.cases.length)html+=`<div class="console-welcome">${b.running?'<span class="spinner"></span>':icon('Terminal',26)}<div><strong>${b.running?'Your agent is executing.':'Your agent is ready for its first run.'}</strong><p>${b.running?`${b.progress.completed} of ${b.progress.total} cases completed.`:'Start with public tests. Tune your prompt. Then challenge the hidden suite.'}</p></div></div>`;
 return html;
}
function paintConsole(){if(!S.builder||!$('#console-body'))return;$('#console-body').innerHTML=consoleHtml();document.querySelectorAll('.console-tab').forEach(el=>el.classList.toggle('active',el.dataset.id===S.builder.tab));const b=S.builder;$('#run-status').textContent=b.running?`RUNNING / ${b.progress.completed} OF ${b.progress.total}`:b.summary?`${b.summary.tier.toUpperCase()} / ${b.kind==='hidden'?'SUBMITTED':'PUBLIC'}`:'READY';$('#run-progress').classList.toggle('hidden',!b.running);$('#run-progress span').style.width=`${b.progress.total?b.progress.completed/b.progress.total*100:3}%`;localize();}
function builderError(message){const text=message?displayError(message):'';const node=$('#builder-error');if(node)node.innerHTML=text?`<div class="callout danger">${icon('Shield',14)} ${esc(text)}</div>`:'';}
function requireLogin(){if(S.user)return true;navigate('/login?next='+uri(location.pathname+location.search));return false;}
async function saveBuild(){if(!requireLogin())throw new Error('Sign in before saving a build.');const b=S.builder;if(!b)throw new Error('Builder is not ready.');if(b.configError)throw new Error(b.configError);if(b.id&&!b.dirty)return b;const result=await post('builds',{...(b.id?{buildId:b.id,currentVersionId:b.currentVersionId}:{}),problemId:b.problem.id,title:b.title,visibility:b.visibility,workflow:b.w});Object.assign(b,{id:result.id,currentVersionId:result.currentVersionId,version:result.version.revision,dirty:false});history.replaceState({},'',`/builder?build=${uri(b.id)}`);$('#version-label').textContent=`v${b.version}`;toast(`Saved immutable version ${b.version}.`);return b;}
function runningButtons(running){const save=$('#save-build'),submit=$('#run-hidden'),run=$('#run-public');if(!save||!submit||!run)return;save.disabled=running;submit.disabled=running;run.innerHTML=running?icon('X',14)+' Cancel':icon('Play',14)+' Run public tests';run.dataset.action=running?'cancel-run':'run-public';}
async function runTests(kind){if(!requireLogin())return;const b=S.builder;if(b.running)return;builderError('');try{await saveBuild();}catch(e){builderError(e);return;}if(S.builder!==b)return;Object.assign(b,{running:true,kind,cases:[],traces:[],summary:null,states:{},tab:kind==='public'?'trace':'results',progress:{completed:0,total:0},controller:new AbortController()});runningButtons(true);paintFlow();paintConsole();try{const response=await fetch('/api/arena/runs',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({buildId:b.id,kind,consent:false}),signal:b.controller.signal});if(!response.ok){const error=await readResponsePayload(response);throw normalizeClientError(error,'Run failed.',response.status);}if(!response.body)throw normalizeClientError({error:{code:'INTERNAL_SERVER_ERROR',message:'Execution stream is unavailable.'}},'Run failed.',502);const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';const consume=event=>{if(event.type==='error')throw normalizeClientError({error:event},'Run failed.',502);if(event.type==='start')b.progress.total=event.total;if(event.type==='progress')b.progress={completed:event.completed,total:event.total};if(event.type==='trace'){const trace={...event.trace,caseNumber:event.caseNumber};b.traces.push(trace);b.states[trace.nodeId]=trace.state;const node=$(`#flow-plane [data-node="${CSS.escape(trace.nodeId)}"]`);if(node){node.classList.remove('running','done','failed');node.classList.add(trace.state);$('.node-state',node).innerHTML=trace.state==='done'?icon('Check',10):trace.state==='running'?'RUN':'';}}if(event.type==='case')b.cases.push(event.result);if(event.type==='complete'){b.summary=event.summary;b.tab='results';b.runId=event.runId;toast(kind==='hidden'?`${event.summary.score.total} points. Your build is on the ${event.summary.tier} leaderboard.`:'Public test run complete.');}if(S.builder===b)paintConsole();};for(;;){const {value,done}=await reader.read();buffer+=decoder.decode(value,{stream:!done});let end;while((end=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,end);buffer=buffer.slice(end+1);if(line.trim())consume(JSON.parse(line));}if(done)break;}if(buffer.trim())consume(JSON.parse(buffer));}catch(e){if(S.builder===b)builderError(e.name==='AbortError'?'Run cancelled. Already completed provider calls may still be billed.':e);}finally{b.running=false;if(S.builder===b){runningButtons(false);paintConsole();}}}
async function loadBuilder(params){const [skills,tools,providers]=await Promise.all([api('skills'),api('tools'),S.user?api('providers'):Promise.resolve(null)]);S.skills=skills;S.tools=tools;S.providers=providers;let build=null,p;if(params.get('build')){build=await api(`builds/${uri(params.get('build'))}${params.get('version')?'?version='+uri(params.get('version')):''}`);if(!build.owner)throw new Error('This build is read-only. Open its detail page and Fork it first.');p=await api('problems/'+uri(build.problem.slug));}else p=await api('problems/'+uri(params.get('problem')||'messy-json-extractor'));S.builder={id:build?.id||null,title:build?.title||`${p.title} / my build`,visibility:build?.visibility||'private',currentVersionId:build?.currentVersionId||null,version:build?.version.revision||1,w:structuredClone(build?.workflow||p.starter),problem:p,dirty:!!build&&build.version.id!==build.currentVersionId,selected:(build?.workflow||p.starter).nodes.find(n=>n.kind==='prompt')?.id,zoom:null,states:{},running:false,cases:[],traces:[],summary:null,kind:'public',tab:'results',progress:{completed:0,total:0},configError:''};return builderHtml();}
async function updateBoard(){const container=$('[data-board-problem]');if(!container)return;const rows=await api(`leaderboard?problemId=${uri(S.board.problemId)}&tier=${S.board.tier}&sort=${S.board.sort}`);if(!$('#board-table'))return;$('#board-table').innerHTML=boardTable(rows);$('#board-note').innerHTML=laneNote(S.board.tier);localize();document.querySelectorAll('[data-action="board-sort"]').forEach(el=>el.classList.toggle('active',el.dataset.value===S.board.sort));}
async function render(){const routeId=++S.routeId;const path=location.pathname,params=new URLSearchParams(location.search);shell('<main class="container page"><div class="loading-state"><span class="spinner"></span> Loading the arena...</div></main>');try{let content;if(path==='/')content=home(await api('overview'));else if(path==='/challenges'){S.problemList=await api('problems');content=challenges(S.problemList);}else if(path.startsWith('/challenges/')){S.board={sort:'overall',tier:'demo',problemId:''};content=challenge(await api('problems/'+uri(path.split('/')[2])));}else if(path==='/leaderboard'){const ps=await api('problems');S.board={sort:'overall',tier:['demo','byok','verified'].includes(params.get('tier'))?params.get('tier'):'demo',problemId:params.get('problem')||''};const rows=await api(`leaderboard?problemId=${uri(S.board.problemId)}&tier=${S.board.tier}`);content=page(heading('THE LEADERBOARD','There is more than one way to win.','Accuracy is only the beginning. Build cheaper. Run faster. Find the smallest winning strategy.',link(icon('Code2')+' Forge a build','/challenges','primary'))+`<div class="field" style="max-width:340px"><label class="label" for="board-problem">Mission</label><select id="board-problem">${option('','All challenges',S.board.problemId)}${ps.map(p=>option(p.id,p.title,S.board.problemId)).join('')}</select></div>`+board(rows,S.board.problemId));}else if(path==='/workshop'){const [skills,tools]=await Promise.all([api('skills'),api('tools')]);content=workshop(skills,tools);}else if(path==='/providers'){if(!S.user){navigate('/login?next=/providers',true);return;}content=providers(await api('providers'));}else if(path==='/problems/new'){if(!S.user){navigate('/login?next=/problems/new',true);return;}content=createProblem();}else if(path.startsWith('/profile')){const id=path.split('/')[2]||'me';if(id==='me'&&!S.user){navigate('/login?next=/profile/me',true);return;}content=profile(await api('profile/'+uri(id)));}else if(path.startsWith('/builds/'))content=buildDetail(await api(`builds/${uri(path.split('/')[2])}${params.get('version')?'?version='+uri(params.get('version')):''}`));else if(path==='/builder'){if(params.get('build')&&!S.user){navigate('/login?next='+uri(path+location.search),true);return;}content=await loadBuilder(params);}else if(path==='/login'){if(S.user){navigate('/challenges',true);return;}content=login();}else content=page(empty('Uncharted territory.','This route is not part of the arena.',link('Back to the arena','/','primary')));if(routeId!==S.routeId)return;shell(content);if(path==='/builder'){paintFlow();paintConsole();const skill=params.get('skill');if(!params.get('build')&&S.skills.some(s=>s.id===skill))addNode('skill',skill);}}catch(e){if(routeId===S.routeId)shell(page(`<div class="callout danger">${icon('Shield')} ${esc(displayError(e))}</div>${link('Back to challenges','/challenges','outline mt-3')}`));}}
function navigate(href,replace=false){const url=new URL(href,location.origin);if(url.origin!==location.origin)return;if(S.builder?.running)S.builder.controller?.abort();if(url.pathname!=='/builder')S.builder=null;history[replace?'replaceState':'pushState']({},'',url.pathname+url.search);window.scrollTo(0,0);void render();}
function safeNext(){const next=new URLSearchParams(location.search).get('next')||'/challenges';return next.startsWith('/')&&!next.startsWith('//')&&!next.includes('\\')?next:'/challenges';}
async function signIn(email,password,name){const data=await request('/api/auth/'+(S.register?'sign-up/email':'sign-in/email'),{method:'POST',body:JSON.stringify({email,password,...(S.register?{name}: {})})});S.user=data.user;toast(S.register?'Welcome to the arena.':'Welcome back, builder.');navigate(safeNext(),true);}
locale?.subscribe(()=>{refreshLocaleControls();});
async function action(el){const act=el.dataset.action,b=S.builder;switch(act){case 'noop':return;case 'logout':await request('/api/auth/sign-out',{method:'POST',body:'{}'});S.user=null;navigate('/');return;case 'toggle-register':S.register=!S.register;shell(login());return;case 'demo-login':el.disabled=true;try{S.register=false;await signIn('demo@agentforge.local','ForgeDemo!2026');}finally{el.disabled=false;}return;case 'board-sort':S.board.sort=el.dataset.value;await updateBoard();return;case 'delete-provider':el.disabled=true;await api('providers/'+uri(el.dataset.id),{method:'DELETE'});toast('Credential deleted. Builds using it must select another provider.');await render();return;case 'fork':if(!requireLogin())return;el.disabled=true;try{const copied=await post(`builds/${uri(el.dataset.id)}/fork`,{versionId:el.dataset.version});toast('Fork created. Provider credentials were not copied.');navigate('/builder?build='+uri(copied.id));}finally{el.disabled=false;}return;case 'save-build':el.disabled=true;try{builderError('');await saveBuild();}catch(e){builderError(e);}finally{el.disabled=false;}return;case 'run-public':await runTests('public');return;case 'run-hidden':await runTests('hidden');return;case 'set-locale':locale?.set(el.dataset.locale);refreshLocaleControls();return;
case 'cancel-run':b.controller?.abort();return;case 'console-tab':b.tab=el.dataset.id;paintConsole();return;case 'add-node':addNode(el.dataset.kind);return;case 'equip':addNode('skill',el.dataset.id);return;case 'delete-node':removeSelected();return;case 'duplicate-node':{const n=b.w.nodes.find(n=>n.id===b.selected);if(!n)return;if(b.w.nodes.length>=24)throw new Error('Use at most 24 nodes.');const copy={...structuredClone(n),id:crypto.randomUUID(),x:n.x+30,y:n.y+140};b.w.nodes.push(copy);b.selected=copy.id;markDirty();paintFlow();paintInspector();return;}case 'delete-edge':b.w.edges=b.w.edges.filter(e=>e.id!==el.dataset.id);markDirty();paintFlow();return;case 'connect-source':b.connecting=el.dataset.id;$('#connect-notice').textContent=locale?.translate('Choose an input port')||'Choose an input port';$('#connect-notice').classList.remove('hidden');return;case 'connect-target':if(b.connecting)connectNode(b.connecting,el.dataset.id);else toast('Select an output port first.');return;case 'canvas-fit':b.zoom=null;paintFlow();return;case 'zoom-in':b.zoom=Math.min(1.5,b.scale+.1);paintFlow();return;case 'zoom-out':b.zoom=Math.max(.25,b.scale-.1);paintFlow();return;case 'copy-config':{const n=b.w.nodes.find(n=>n.id===b.selected),value=n?.config[el.dataset.key];await navigator.clipboard.writeText(typeof value==='object'?JSON.stringify(value,null,2):String(value||''));toast('Copied to clipboard.');return;}case 'reset-prompt':{const n=b.w.nodes.find(n=>n.id===b.selected);n.config=structuredClone(b.problem.starter.nodes.find(n=>n.kind==='prompt').config);markDirty();paintInspector();paintFlow();return;}case 'export':{const blob=new Blob([JSON.stringify(b.w,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='agentforge-workflow.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Workflow exported. No API key values are stored in workflows.');return;}}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el&&!el.disabled){event.preventDefault();void action(el).catch(e=>toast(displayError(e),true));return;}const a=event.target.closest('a[href]');if(a&&!a.hasAttribute('download')&&!a.target&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&a.getAttribute('href').startsWith('/')){event.preventDefault();navigate(a.getAttribute('href'));}});
document.addEventListener('submit',async event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const values=Object.fromEntries(new FormData(form)),submit=form.querySelector('button[type="submit"]');if(submit)submit.disabled=true;try{if(form.id==='auth-form'){if($('#auth-error'))$('#auth-error').textContent='';await signIn(values.email,values.password,values.name);}if(form.id==='provider-form'){const body={...values,inputPrice:values.inputPrice===''?null:Number(values.inputPrice),outputPrice:values.outputPrice===''?null:Number(values.outputPrice)};form.elements.apiKey.value='';await post('providers',body);toast('Credential encrypted with AES-256-GCM.');await render();}if(form.id==='problem-form'){const result=await post('problems',values);$('#problem-result').innerHTML=`<div class="callout">${icon('Check')} ${esc(result.message)} <a href="/profile/me" class="section-link">View profile ${icon('ArrowUpRight',12)}</a></div>`;localize();form.reset();toast('Problem submitted to the pending queue.');}if(form.id==='failure-form'){const result=await post('failure-cases',{...values,consent:false});$('#failure-result').innerHTML=`<div class="callout ${result.status==='verified'?'':'purple'}">${icon(result.status==='verified'?'Target':'ShieldCheck')} ${esc(result.message)}</div>${result.actual?`<div class="eyebrow mt-2 mb-2">ACTUAL OUTPUT / CANDIDATE</div><pre>${esc(result.actual)}</pre>`:''}`;localize();toast(result.message);}}catch(e){if(form.id==='auth-form'&&$('#auth-error'))$('#auth-error').textContent=displayError(e);else if(form.id==='failure-form'&&$('#failure-result'))$('#failure-result').innerHTML=`<div class="callout danger">${esc(displayError(e))}</div>`;else toast(displayError(e),true);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('input',event=>{const el=event.target,b=S.builder;if(el.id==='challenge-search'){$('#challenge-cards').innerHTML=S.problemList.filter(p=>`${p.title} ${p.description} ${p.tags.join(' ')} ${locale?.translate(p.title)||''} ${locale?.translate(p.description)||''} ${p.tags.map(tag=>locale?.translate(tag)||'').join(' ')}`.toLowerCase().includes(el.value.toLowerCase())).map(challengeCard).join('');localize();return;}if(!b)return;if(el.id==='build-title'){b.title=el.value;markDirty();return;}if(el.id==='node-label'){const n=b.w.nodes.find(n=>n.id===b.selected);if(n){n.label=el.value;const label=$(`[data-node="${CSS.escape(n.id)}"] .node-title`);if(label)label.textContent=n.label;markDirty();}return;}const key=el.dataset.config;if(!key||el.tagName==='SELECT')return;const n=b.w.nodes.find(n=>n.id===b.selected);if(!n)return;try{let value=el.value;if(key==='schema'){value=JSON.parse(value);if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('Schema must be a JSON object.');}else if(key==='values')value=value.split('\n').filter(Boolean);else if(['maxTokens','temperature','maxLength'].includes(key))value=Number(value);n.config[key]=value;b.configError='';if($('#config-error'))$('#config-error').textContent='';markDirty();const count=$('#count-'+key),tokens=$('#tokens-'+key);if(count)count.textContent=`${el.value.length} chars`;if(tokens)tokens.textContent=`~${Math.ceil(new TextEncoder().encode(el.value).length/4)} tokens / est.`;const meta=$(`[data-node="${CSS.escape(n.id)}"] .node-meta`);if(meta)meta.textContent=nodeMeta(n);}catch{b.configError='Invalid JSON Schema. Correct it before saving.';if($('#config-error'))$('#config-error').textContent=locale?.translate(b.configError)||b.configError;}});
document.addEventListener('change',event=>{const el=event.target,b=S.builder;if(el.id==='board-tier'){S.board.tier=el.value;void updateBoard().catch(e=>toast(displayError(e),true));return;}if(el.id==='board-problem'){S.board.problemId=el.value;void updateBoard().catch(e=>toast(displayError(e),true));return;}if(!b)return;if(el.id==='build-visibility'){b.visibility=el.value;markDirty();return;}const key=el.dataset.config;if(!key||el.tagName!=='SELECT')return;const n=b.w.nodes.find(n=>n.id===b.selected);if(!n)return;n.config[key]=el.value;if(key==='credentialId')n.config.modelId=el.value==='demo'?'demo-forge':S.providers?.credentials.find(p=>p.id===el.value)?.modelId||'';if(key==='format'){if(el.value==='json'){n.config.schema=structuredClone(defaultSchema);delete n.config.values;}else{delete n.config.schema;if(el.value==='enum')n.config.values=routeLabels.slice();else delete n.config.values;}}if(key==='toolId'&&el.value!=='json-validator')delete n.config.schema;if(key==='skillId'&&el.value!=='structured')delete n.config.schema;markDirty();paintInspector();paintFlow();});
let dragging=null;
document.addEventListener('pointerdown',event=>{const node=event.target.closest('#flow-plane [data-node]'),b=S.builder;if(!node||!b||event.target.closest('.port')||event.button!==0)return;event.preventDefault();const n=b.w.nodes.find(n=>n.id===node.dataset.node);if(!n)return;selectNode(n.id);dragging={id:n.id,x:event.clientX,y:event.clientY,nx:n.x,ny:n.y,scale:b.scale,pointer:event.pointerId,element:node};node.setPointerCapture(event.pointerId);});
document.addEventListener('pointermove',event=>{if(!dragging||!S.builder)return;const n=S.builder.w.nodes.find(n=>n.id===dragging.id);if(!n)return;n.x=Math.max(10,Math.round((dragging.nx+(event.clientX-dragging.x)/dragging.scale)/10)*10);n.y=Math.max(65,Math.round((dragging.ny+(event.clientY-dragging.y)/dragging.scale)/10)*10);dragging.element.style.left=n.x+'px';dragging.element.style.top=n.y+'px';const svg=$('#flow-plane svg.connections');if(svg)svg.innerHTML=S.builder.w.edges.map(edge=>`<path d="${wirePath(S.builder.w,edge)}" stroke="#71865a" stroke-width="1.7" fill="none"/><path d="${wirePath(S.builder.w,edge)}" class="wire-delete" fill="none" data-action="delete-edge" data-id="${esc(edge.id)}"/>`).join('');});
document.addEventListener('pointerup',event=>{if(!dragging)return;const moved=Math.abs(event.clientX-dragging.x)+Math.abs(event.clientY-dragging.y)>3;try{dragging.element.releasePointerCapture(dragging.pointer);}catch{}dragging=null;if(moved){markDirty();paintFlow();}});
document.addEventListener('dragstart',event=>{const el=event.target.closest('[data-action="add-node"]');if(el)event.dataTransfer.setData('application/agentforge',el.dataset.kind);});
document.addEventListener('dragover',event=>{if(event.target.closest('#flow-viewport')){event.preventDefault();event.dataTransfer.dropEffect='move';}});
document.addEventListener('drop',event=>{const view=event.target.closest('#flow-viewport');if(!view||!S.builder)return;event.preventDefault();const kind=event.dataTransfer.getData('application/agentforge');if(!kinds[kind])return;const rect=view.getBoundingClientRect();addNode(kind,undefined,{x:Math.max(10,(event.clientX-rect.left+view.scrollLeft)/S.builder.scale),y:Math.max(65,(event.clientY-rect.top+view.scrollTop)/S.builder.scale)});});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.matches('.port')){event.preventDefault();event.target.click();}if(!S.builder||/^(INPUT|TEXTAREA|SELECT)$/.test(event.target.tagName))return;if(event.key==='Escape'){S.builder.connecting=null;$('#connect-notice')?.classList.add('hidden');}if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();removeSelected();}});
window.addEventListener('popstate',()=>{S.builder?.controller?.abort();S.builder=null;void render();});
window.addEventListener('resize',()=>{if(S.builder)paintFlow();});
window.addEventListener('beforeunload',event=>{if(S.builder?.dirty){event.preventDefault();event.returnValue='';}});
(async()=>{try{const [boot,session]=await Promise.all([api('boot'),request('/api/auth/get-session')]);S.boot=boot;S.user=session?.user||null;await render();}catch(e){shell(page(`<div class="callout danger">${esc(displayError(e))}</div>`));}})();
